#!/usr/bin/env python3
"""Post-process the Android project generated by `flutter create`."""
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parent.parent


def patch_manifest() -> None:
    p = ROOT / "android/app/src/main/AndroidManifest.xml"
    s = p.read_text()
    if "android.permission.INTERNET" not in s:
        s = s.replace(
            "<application",
            '    <uses-permission android:name="android.permission.INTERNET"/>\n'
            '    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE"/>\n'
            "    <application",
            1,
        )
    s = re.sub(r'android:label="[^"]*"', 'android:label="Nexus"', s, count=1)
    if "usesCleartextTraffic" not in s:
        s = s.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
    p.write_text(s)
    print("[patch] manifest ok")


def patch_gradle() -> None:
    for name in ("android/app/build.gradle.kts", "android/app/build.gradle"):
        p = ROOT / name
        if not p.exists():
            continue
        s = p.read_text()
        s = s.replace("minSdk = flutter.minSdkVersion", "minSdk = 23")
        s = s.replace("minSdkVersion flutter.minSdkVersion", "minSdkVersion 23")
        s = re.sub(r"minSdkVersion\s+\d+", "minSdkVersion 23", s)
        p.write_text(s)
        print(f"[patch] {name} minSdk ok")


def drop_stub_test() -> None:
    t = ROOT / "test/widget_test.dart"
    if t.exists() and "MyApp" in t.read_text():
        t.unlink()
        print("[patch] removed generated widget_test.dart")


def main() -> int:
    if not (ROOT / "android").exists():
        print("android/ missing; run `flutter create --platforms=android .` first", file=sys.stderr)
        return 1
    patch_manifest()
    patch_gradle()
    drop_stub_test()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
